 await page.evaluate(()=>{
  const original=window.lootlazyRequest;window.achievementWrites=[];window.achievementFixture=Array.from({length:105},(_,i)=>({name:'ACH_'+i,title:'Achievement '+i,description:'Fixture description '+i,achieved:i%2===0,unlockedAt:i===0?1700000000:0}));
  window.lootlazyRequest=async(route,body)=>{if(route==='/api/achievements/games')return {steamId:'76561198000000001',games:[{appId:730,name:'Counter-Strike 2',risky:true,riskReason:'anti_cheat'},{appId:431960,name:'Wallpaper Engine',risky:false,riskReason:'unknown'},...Array.from({length:104},(_,i)=>({appId:10000+i,name:'Owned game '+i,risky:false,riskReason:'unknown'}))]};if(route==='/api/achievements/list'){if(window.achievementReadError){window.achievementReadError=false;throw Error('operation_failed: achievements_read_failed');}return {appId:body.appId,steamId:'76561198000000001',achievements:structuredClone(window.achievementFixture)};}if(route==='/api/achievements/apply'){window.achievementWrites.push(structuredClone(body));if(window.achievementApplyError){const reason=window.achievementApplyError;window.achievementApplyError=null;throw Error('operation_failed: '+reason);}for(const change of body.changes)window.achievementFixture.find(a=>a.name===change.name).achieved=change.achieved;return {appId:body.appId,steamId:body.steamId,achievements:structuredClone(window.achievementFixture)};}return original(route,body);};
 });
